#pragma once
// File was generated by Claude.
// 5R arm (base + planar 3R + wrist roll), e.g. SO-101 style:
//   the 4R solver for the point on the roll axis, then the roll joint from the desired tool x-axis.
// The tool point may lie off the roll axis (radial offset); its effect on the 4R target is handled
// in closed form for a vertical approach and by fixed-point iteration otherwise.
#include <array>
#include <bitset>
#include <cmath>
#include <cstddef>
#include <numbers>
#include <optional>
#include <type_traits>
#include "linalg/matrix.hpp"
#include "kinematics/arm_geometry.hpp"
#include "kinematics/general.hpp"
#include "kinematics/analytic/analytic_solutions.hpp"
#include "kinematics/analytic/base+3planar.hpp"

namespace kinematics {

template <>
struct BranchFlags<Twist::Zero, Twist::Plus90, Twist::Zero, Twist::Zero, Twist::Plus90> {
    enum Flag : std::size_t {
        reach_front_i,
        elbow_up_i,
        tool_flip_i,        // tool x-axis along -x_target (two-finger symmetry)
        count
    };
};

namespace arm5R_bnpr {

using Flags = BranchFlags<Twist::Zero, Twist::Plus90, Twist::Zero, Twist::Zero, Twist::Plus90>;

template<std::floating_point T>
using Solutions = RevoluteAnalyticSolutions<T, Twist::Zero, Twist::Plus90, Twist::Zero, Twist::Zero, Twist::Plus90>;

template<std::floating_point T>
using Arm = RevoluteArm<T, Twist::Zero, Twist::Plus90, Twist::Zero, Twist::Zero, Twist::Plus90>;

template<std::floating_point T>
using Branch = RevoluteBranch<T, Twist::Zero, Twist::Plus90, Twist::Zero, Twist::Zero, Twist::Plus90>;

// Inline tool on the roll axis: axial length along the approach, radial offset along tool x.
template<std::floating_point T>
using Tool = ToolLink<T, Twist::Zero>;

/*
target:   desired tool point (world)
theta:    approach angle, 0 = from above (as for the 4R solver)
x_target: desired direction of the tool's x-axis (unit vector, world). Admissible if it deviates
          from the plane perpendicular to the approach by at most jaw_tol (sine of the angle);
          the tool x-axis is then its projection onto that plane.
pos_tol:  convergence tolerance of the fixed-point iteration (tilted approach only)
The scalar type T is taken from the arm.
*/
template<std::floating_point T>
Solutions<T> inverse(std::type_identity_t<const linalg::Vector<T, 3>&> target,
                     std::type_identity_t<T> theta,
                     std::type_identity_t<const linalg::Vector<T, 3>&> x_target,
                     const Arm<T>& arm, const Tool<T>& tool,
                     std::type_identity_t<T> jaw_tol, std::type_identity_t<T> pos_tol, int max_iter = 10)
{
    constexpr T pi = std::numbers::pi_v<T>;
    Solutions<T> solutions{};

    // The 4R sub-problem: its tool frame is the roll joint's frame at roll angle 0.
    const auto arm4  = arm.prefix(at<4>);
    const auto tool4 = arm.prefix_tool(at<4>);
    const T radial = tool.translation()[0];
    const T axial  = tool.translation()[2];

    // columns 1..3 of a pose matrix: the frame's x, y, z axes in world coordinates
    auto axis = [](const linalg::Matrix<T, 4, 4>& pose, std::size_t col) {
        linalg::Vector<T, 3> v;
        for (std::size_t k = 0; k < 3; ++k) v[k] = pose[k + 1, col];
        return v;
    };
    // 4R target (point on the roll axis) for a given approach a and tool x-axis s
    auto axis_point = [&](const linalg::Vector<T, 3>& a, const linalg::Vector<T, 3>& s) {
        const linalg::Vector<T, 3> p = target - axial * a - radial * s;
        return std::array<T, 3>{p[0], p[1], p[2]};
    };
    // projection of k onto the plane perpendicular to a; nullopt if not admissible
    auto project = [&](const linalg::Vector<T, 3>& k, const linalg::Vector<T, 3>& a)
        -> std::optional<linalg::Vector<T, 3>> {
        const T ka = linalg::dot(k, a);
        if (std::abs(ka) > jaw_tol) return std::nullopt;
        const linalg::Vector<T, 3> s = k - ka * a;
        const T len = linalg::norm2(s);
        if (len == T(0)) return std::nullopt;
        return (T(1) / len) * s;
    };
    // stores a 4R branch together with the roll that turns the roll frame's x-axis onto k
    auto store = [&](const arm4R_bnp::Branch<T>& br, bool flip, const linalg::Vector<T, 3>& k) {
        const auto pose = forward(br.angles(), arm4, tool4);
        const T roll = std::atan2(linalg::dot(k, axis(pose, 2)), linalg::dot(k, axis(pose, 1)));
        std::bitset<Flags::count> flags(0);
        flags[Flags::reach_front_i] = br.flags()[arm4R_bnp::Flags::reach_front_i];
        flags[Flags::elbow_up_i]    = br.flags()[arm4R_bnp::Flags::elbow_up_i];
        flags[Flags::tool_flip_i]   = flip;
        const auto& phi = br.angles();
        solutions[flags.to_ulong()].emplace(flags, std::array<T, 5>{phi[0], phi[1], phi[2], phi[3], roll});
    };

    for (int flip = 0; flip < 2; ++flip) {
        // Without a radial offset the flipped tool needs the same arm pose: roll + pi.
        if (flip == 1 && radial == T(0)) {
            for (std::size_t i = 0; i < solutions.size(); ++i) {
                if (!solutions[i] || solutions[i]->flags()[Flags::tool_flip_i]) continue;
                auto flags = solutions[i]->flags();
                flags[Flags::tool_flip_i] = true;
                auto phi = solutions[i]->angles();
                phi[4] = std::remainder(phi[4] + pi, 2 * pi);
                solutions[flags.to_ulong()].emplace(flags, phi);
            }
            break;
        }

        const linalg::Vector<T, 3> k = (flip ? T(-1) : T(1)) * x_target;

        // Closed form: vertical approach. a and s do not depend on the base angle.
        if (theta == T(0)) {
            linalg::Vector<T, 3> a;
            a[0] = T(0); a[1] = T(0); a[2] = T(-1);
            const auto s = project(k, a);
            if (!s) return solutions;
            const auto sols = kinematics::inverse<T>(axis_point(a, *s), theta, arm4, tool4);
            for (const auto& br : sols)
                if (br) store(*br, flip, k);
            continue;
        }

        // Tilted approach: fixed-point iteration per 4R branch.
        // Start from the axis point of an arm without lateral offsets: its approach direction
        // tilts by theta towards the target, whichever branch reaches it.
        std::array<T, 3> p0{target[0], target[1], target[2]};
        if (const T rho = std::hypot(target[0], target[1]); rho > T(0)) {
            linalg::Vector<T, 3> a;
            a[0] = std::sin(theta) * target[0] / rho;
            a[1] = std::sin(theta) * target[1] / rho;
            a[2] = -std::cos(theta);
            if (const auto s = project(k, a)) p0 = axis_point(a, *s);
        }
        for (std::size_t slot = 0; slot < arm4R_bnp::Solutions<T>{}.size(); ++slot) {
            std::array<T, 3> p = p0;
            for (int it = 0; it < max_iter; ++it) {
                const auto sols = kinematics::inverse<T>(p, theta, arm4, tool4);
                if (!sols[slot]) break;                               // branch lost
                const auto pose = forward(sols[slot]->angles(), arm4, tool4);
                const auto a = axis(pose, 3);
                const auto s = project(k, a);
                if (!s) break;                                       // tool x-axis not admissible
                const auto p_new = axis_point(a, *s);
                const T step = std::hypot(p_new[0] - p[0], p_new[1] - p[1], p_new[2] - p[2]);
                p = p_new;
                if (step <= pos_tol) {
                    const auto final_sols = kinematics::inverse<T>(p, theta, arm4, tool4);
                    if (final_sols[slot]) store(*final_sols[slot], flip, k);
                    break;
                }
            }
        }
    }
    return solutions;
}

}  // namespace arm5R_bnpr
}  // namespace kinematics